//! Acceptance 5: the legacy `/api/share/*` read-only face requires the
//! usage session or the control token, and the public ingress never
//! reverse-proxies it.
//!
//! The expected bodies come from `tests/fixtures/rust_console_reads_rev1.json`,
//! generated by `tests/generate_rust_console_reads_fixture.py` from the real
//! Python cloud `usagesrv.Handler`.

mod support;

use serde_json::{json, Value};

use support::*;

const CONTROL_TOKEN: &str = "fixture-control-token";

fn start_api_share_console(temp: &um_test_harness::TempDataDir, fixture: &Value) -> Console {
    let mut seams = StaticShareSeams::new();
    seams.broker_snapshot = Some(json!({
        "name": "broker-client",
        "state": "ok",
        "broker": {"version": "2.0.0", "pid": 4242},
    }));
    start_api_share_console_with(temp, fixture, std::sync::Arc::new(seams))
}

fn start_api_share_console_with(
    temp: &um_test_harness::TempDataDir,
    fixture: &Value,
    seams: std::sync::Arc<dyn um_console::ShareReadSeams>,
) -> Console {
    let control = temp.path().join("control-token");
    std::fs::write(&control, CONTROL_TOKEN).expect("control token");
    let backend = temp.path().join("share-backend");
    std::fs::create_dir_all(&backend).expect("backend dir");
    std::fs::write(
        backend.join("usage-share-backend.jsonl"),
        fixture["shareUsage"]["ledger"].as_str().expect("ledger"),
    )
    .expect("write ledger");
    let key = temp.path().join("share-secret.key");
    let hex = fixture["metadata"]["fixtureKeyHex"]
        .as_str()
        .expect("fixture key");
    let mut bytes = Vec::with_capacity(hex.len() / 2);
    for pair in hex.as_bytes().chunks(2) {
        let high = (pair[0] as char).to_digit(16).expect("hex");
        let low = (pair[1] as char).to_digit(16).expect("hex");
        bytes.push((high * 16 + low) as u8);
    }
    std::fs::write(&key, bytes).expect("write key");
    start_console_with_seams(
        temp,
        |config| {
            config.share_store_file = Some(temp.path().join("share.db"));
            config.share_backend_dir = Some(backend.clone());
            config.control_token_file = Some(control.clone());
            config.share_secret_key_file = Some(key.clone());
        },
        seams,
    )
}

fn remove_checked_at(body: &mut Value) {
    if let Some(object) = body.as_object_mut() {
        object.remove("checkedAt");
    }
}

#[test]
fn session_and_control_token_read_every_share_read_face() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let console = start_api_share_console(&temp, &fixture);
    console.state().session.issue("fixture-session".to_string());
    let cases = fixture["apiShare"].as_object().expect("cases");
    let targets = [
        ("status", "/api/share/status".to_string()),
        ("keys", "/api/share/keys".to_string()),
        ("key", "/api/share/keys/key-active-1".to_string()),
        ("secret", "/api/share/keys/key-active-1/secret".to_string()),
        ("operation", "/api/share/operations/op-1".to_string()),
        ("usage", "/api/share/usage".to_string()),
        ("usageRequests", "/api/share/usage/requests".to_string()),
    ];
    for (name, target) in targets {
        for (auth, headers) in [
            ("control", vec![("X-Admin-Control", CONTROL_TOKEN)]),
            ("session", vec![("Cookie", "usage_session=fixture-session")]),
        ] {
            let key = format!("{auth}.{name}");
            let expected = &cases[key.as_str()];
            let mut request = ClientRequest::get(&target);
            for (header, value) in headers {
                request = request.header(header, value);
            }
            let response = client_request(console.addr, &request).expect("request");
            let mut body = response.json();
            remove_checked_at(&mut body);
            assert_eq!(
                u64::from(response.status),
                expected["status"].as_u64().unwrap(),
                "{auth}.{name}"
            );
            assert_eq!(body, expected["body"], "{auth}.{name}");
            assert_eq!(
                response.header("cache-control"),
                expected["cacheControl"].as_str(),
                "{auth}.{name}"
            );
        }
    }
}

#[test]
fn missing_wrong_or_duplicate_credentials_are_refused() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let console = start_api_share_console(&temp, &fixture);
    let cases = fixture["apiShare"].as_object().expect("cases");
    let requests = [
        ("noCredentials", ClientRequest::get("/api/share/status")),
        (
            "wrongControl",
            ClientRequest::get("/api/share/status").header("X-Admin-Control", "wrong-token"),
        ),
        (
            "duplicateHeader",
            ClientRequest::get("/api/share/status")
                .header("X-Admin-Control", CONTROL_TOKEN)
                .header("X-Admin-Control", CONTROL_TOKEN),
        ),
        (
            "foreignOrigin",
            ClientRequest::get("/api/share/status")
                .header("X-Admin-Control", CONTROL_TOKEN)
                .header("Origin", "http://evil.example"),
        ),
    ];
    for (name, request) in requests {
        let expected = &cases[name];
        let response = client_request(console.addr, &request).expect("request");
        assert_eq!(
            u64::from(response.status),
            expected["status"].as_u64().unwrap(),
            "{name}"
        );
        assert_eq!(response.json(), expected["body"], "{name}");
        assert_eq!(
            response.header("cache-control"),
            expected["cacheControl"].as_str(),
            "{name}"
        );
    }
}

#[test]
fn the_public_ingress_never_reverse_proxies_the_share_management_face() {
    let root = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../..");
    let ingress =
        std::fs::read_to_string(root.join("um-cloud-deploy/config/cloudflared.yml.example"))
            .expect("cloudflared example");
    assert!(!ingress.contains("/api/share"));
    assert!(!ingress.contains("8002"));
    for path in [
        "/v1/models",
        "/v1/chat/completions",
        "/v1/messages",
        "/v1/responses",
    ] {
        assert!(ingress.contains(path), "{path} must stay public");
    }
}

#[test]
fn raw_status_without_a_broker_is_an_honest_offline_snapshot() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let console = start_api_share_console_with(
        &temp,
        &fixture,
        std::sync::Arc::new(StaticShareSeams::new()),
    );
    let response = client_request(
        console.addr,
        &ClientRequest::get("/api/share/status").header("X-Admin-Control", CONTROL_TOKEN),
    )
    .expect("request");
    assert_eq!(response.status, 200);
    assert_eq!(response.json()["broker"]["state"], json!("offline"));
    assert_eq!(response.json()["broker"]["name"], json!("noop"));
}

#[test]
fn write_methods_now_use_the_s6b_write_face() {
    let fixture = reads_fixture();
    let temp = temp();
    seed_share_store(&temp, &fixture["shareStatus"]["storeSeed"]);
    let console = start_api_share_console(&temp, &fixture);
    let missing = client_request(
        console.addr,
        &ClientRequest::post("/api/share/keys", b"{}".to_vec())
            .json_body(json!({"name": "no-credentials"}).to_string().into_bytes()),
    )
    .expect("request");
    assert_eq!(missing.status, 401);
    assert_eq!(
        missing.json(),
        json!({"error": "share management credentials required"})
    );

    let created = client_request(
        console.addr,
        &ClientRequest::post("/api/share/keys", b"{}".to_vec())
            .header("X-Admin-Control", CONTROL_TOKEN)
            .json_body(json!({"name": "created-by-s6b"}).to_string().into_bytes()),
    )
    .expect("request");
    assert_eq!(created.status, 201);
    assert_eq!(created.json()["name"], json!("created-by-s6b"));
}
